import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr00108Controller {
  @Post('/card-transactions/receive')
  @HttpCode(200)
  async receiveCardTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const cardIdText = String(data['creditCardId'] ?? '');
    if (cardIdText === '' || !Number.isInteger(Number(cardIdText))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신용카드를 선택해 주세요.');
    }
    const startDate = String(data['startDate'] ?? '');
    const endDate = String(data['endDate'] ?? '');
    if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
      throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 기간을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const cards = await db.query(
        'SELECT credit_card_id AS "creditCardId" FROM credit_card WHERE credit_card_id = CAST(:creditCardId AS bigint)',
        { creditCardId: cardIdText },
      );
      if (cards.length === 0) {
        throw new ApiError(404, 'CREDIT_CARD_NOT_FOUND', '등록되지 않은 신용카드입니다.');
      }
      const range = await db.query(
        'SELECT CAST(:startDate AS date) > CAST(:endDate AS date) AS "invalid"',
        { startDate, endDate },
      );
      if (range[0] && range[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '시작일이 종료일보다 늦을 수 없습니다.');
      }
      // TODO(질문): 카드사 연동 호출 방법·수신 데이터 형식(승인번호·승인일시·합계금액)이 입력에 없어 수신 저장은 구현하지 못했다.
      const receivedCount = 0;
      const errorReasons: string[] = [];
      return { receivedCount, errorReasons };
    });
  }

  @Get('/card-transactions')
  async listCardTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const pageNum = Number(query['page'] ?? 0);
    const sizeNum = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(pageNum) || pageNum < 0 || !Number.isInteger(sizeNum) || sizeNum < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeNum, MAX_SIZE);
    const params: Record<string, unknown> = { size, offset: pageNum * size };
    const conditions: string[] = [];
    const cardIdText = String(query['creditCardId'] ?? '');
    if (cardIdText !== '') {
      if (!Number.isInteger(Number(cardIdText))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '신용카드 값이 올바르지 않습니다.');
      }
      conditions.push('credit_card_id = CAST(:creditCardId AS bigint)');
      params['creditCardId'] = cardIdText;
    }
    const startDate = String(query['startDate'] ?? '');
    if (startDate !== '') {
      if (!DATE_PATTERN.test(startDate)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '승인일 시작 형식이 올바르지 않습니다.');
      }
      conditions.push('approved_at >= CAST(:startDate AS date)');
      params['startDate'] = startDate;
    }
    const endDate = String(query['endDate'] ?? '');
    if (endDate !== '') {
      if (!DATE_PATTERN.test(endDate)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '승인일 종료 형식이 올바르지 않습니다.');
      }
      conditions.push('approved_at < CAST(:endDate AS date) + 1');
      params['endDate'] = endDate;
    }
    const where = conditions.length > 0 ? ' WHERE ' + conditions.join(' AND ') + ' ' : ' ';
    return transaction(async (db) => {
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM card_transaction' + where,
        params,
      );
      const items = await db.query(
        'SELECT card_transaction_id AS "cardTransactionId", credit_card_id AS "creditCardId", approval_no AS "approvalNo", approved_at AS "approvedAt", merchant_name AS "merchantName", total_amount AS "totalAmount", evidence_type AS "evidenceType" FROM card_transaction' +
          where +
          'ORDER BY approved_at DESC, card_transaction_id DESC LIMIT :size OFFSET :offset',
        params,
      );
      return { items, page: pageNum, size, total: Number(countRows[0]['total']) };
    });
  }
}

