import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

interface ReceiveResult {
  receivedCount: number;
  errorReasons: unknown[];
}

export default function FnSfr00108Page({ role, notify }: PageProps) {
  const [cardId, setCardId] = useState<number | string>('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [recvCard, setRecvCard] = useState<number | string>('');
  const [recvStart, setRecvStart] = useState('');
  const [recvEnd, setRecvEnd] = useState('');
  const [result, setResult] = useState<ReceiveResult | undefined>(undefined);

  const list = useData<Page>(
    () => call<Page>('GET', '/card-transactions', role, undefined, { ...applied, page, size: 20 }),
    [role, applied, page],
  );

  const search = () => {
    setPage(0);
    setApplied({ creditCardId: cardId, startDate: from, endDate: to });
  };

  const reset = () => {
    setCardId('');
    setFrom('');
    setTo('');
    setPage(0);
    setApplied({});
  };

  const receive = async () => {
    if (recvCard === '') {
      throw new Error('신용카드를 선택해 주세요.');
    }
    if (recvStart === '' || recvEnd === '') {
      throw new Error('수신 기간을 입력해 주세요.');
    }
    const res = await call<ReceiveResult>('POST', '/card-transactions/receive', role, {
      creditCardId: recvCard,
      startDate: recvStart,
      endDate: recvEnd,
    });
    setResult(res);
    notify('카드 사용 내역을 수신했습니다.');
    setOpen(false);
    list.reload();
  };

  const data = list.data;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>수신 현황</h2>
        <Tiles
          items={[
            ['조회된 내역', <Num value={data ? data.total : 0} />],
            ['최근 수신 건수', <Num value={result ? result.receivedCount : 0} />],
            ['최근 반영 제외', <Num value={result ? result.errorReasons.length : 0} />],
          ]}
        />
        {result && result.errorReasons.length > 0 && (
          <ul>
            {result.errorReasons.map((r, i) => (
              <li key={i}>{String(r)}</li>
            ))}
          </ul>
        )}
      </section>
      <section className="box span-12">
        <h2>카드 사용 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="신용카드 ID">
            <LookupSelect table="credit_card" role={role} value={cardId} onChange={setCardId} />
          </Field>
          <Field label="승인일 시작">
            <DateInput value={from} onChange={setFrom} />
          </Field>
          <Field label="승인일 종료">
            <DateInput value={to} onChange={setTo} />
          </Field>
        </Filters>
        <Band total={data ? data.total : undefined}>
          <button type="button" onClick={() => setOpen(true)}>
            카드사 내역 수신
          </button>
        </Band>
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          columns={[
            { key: 'creditCardId', label: '신용카드 ID', render: (r) => <RefName table="credit_card" role={role} value={r['creditCardId']} /> },
            { key: 'approvalNo', label: '승인번호' },
            { key: 'approvedAt', label: '승인일시', render: (r) => <DateText value={r['approvedAt']} time /> },
            { key: 'merchantName', label: '가맹점명' },
            { key: 'totalAmount', label: '합계금액', render: (r) => <Num value={r['totalAmount']} /> },
            { key: 'evidenceType', label: '증빙 유형', render: (r) => <Badge value={r['evidenceType']} /> },
          ]}
          rows={data ? data.items : []}
          empty="수신된 사용 내역이 없습니다."
        />
        <Pager page={page} size={data ? data.size : 20} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {open && (
        <Drawer title="카드사 내역 수신" onClose={() => setOpen(false)}>
          <Form onSubmit={receive} submit="수신">
            <Field label="신용카드 ID" required>
              <LookupSelect table="credit_card" role={role} value={recvCard} onChange={setRecvCard} />
            </Field>
            <Field label="수신 시작일" required>
              <DateInput value={recvStart} onChange={setRecvStart} />
            </Field>
            <Field label="수신 종료일" required>
              <DateInput value={recvEnd} onChange={setRecvEnd} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
